                await check_unpaid(de.otmp);
                if (de.otmp.cursed && !rn2(WAND.BACKFIRE_CHANCE)) {
                    await wand_explode(de.otmp, 0);
                    de.ret = ECMD.TIME;
                    return FALSE;
                }
